#!/usr/bin/env bash
set -euo pipefail

# Hand the APNs device token to Capacitor (Louis, 2026-10-24).
#
# THE BUG THAT COST A FORTNIGHT. Apple delivers a push token to the app's
# UIApplicationDelegate, and nowhere else. Capacitor's PushNotifications
# plugin listens for it on NotificationCenter, so the delegate has to forward
# it - every Capacitor push app must add these two methods by hand, and the
# plugin's README says so.
#
# ios/ is gitignored and regenerated by `npx cap add ios` on every build, and
# the AppDelegate that generates has neither method. So iOS was receiving the
# token, handing it to a delegate that did nothing with it, and the plugin
# heard nothing. No "registration" event. No "registrationError" either -
# that is the second method, and its absence is why a failure never showed up
# anywhere.
#
# From the outside this is indistinguishable from Apple ignoring the app, and
# it survived: a clean delete-and-reinstall, four TestFlight builds, a correct
# aps-environment in both the entitlements and the signing profile, a working
# permission prompt, and a bridge that provably reaches Swift. The device
# ruled the rest out one at a time - events DO reach JavaScript
# ("appStateChange" fires), so the token was never arriving to be dropped.
#
# native_push_tokens has held zero rows since the day it was created, for
# every user, which is exactly what a delegate that drops every token looks
# like.

APPDELEGATE="ios/App/App/AppDelegate.swift"

if [ ! -f "$APPDELEGATE" ]; then
  echo "No $APPDELEGATE - run this after 'npx cap add ios'." >&2
  exit 1
fi

if grep -q "didRegisterForRemoteNotificationsWithDeviceToken" "$APPDELEGATE"; then
  echo "AppDelegate already forwards the APNs token; nothing to do."
  exit 0
fi

# Insert before the final closing brace of the file, which closes the class.
LAST_BRACE=$(grep -n '^}' "$APPDELEGATE" | tail -1 | cut -d: -f1)
if [ -z "$LAST_BRACE" ]; then
  echo "Could not find the end of the AppDelegate class in $APPDELEGATE." >&2
  exit 1
fi

TMP=$(mktemp)
head -n "$((LAST_BRACE - 1))" "$APPDELEGATE" > "$TMP"

cat >> "$TMP" <<'SWIFT'

    // MARK: - Remote notifications
    //
    // Added by scripts/ios-push-appdelegate.sh. Apple hands the device token
    // to this delegate and nowhere else; Capacitor's PushNotifications plugin
    // listens for it on NotificationCenter. Without these two methods the
    // token is received and silently dropped, and no error is reported
    // either - which is exactly how this failed, invisibly, for a fortnight.

    func application(_ application: UIApplication,
                     didRegisterForRemoteNotificationsWithDeviceToken deviceToken: Data) {
        NotificationCenter.default.post(name: .capacitorDidRegisterForRemoteNotifications,
                                        object: deviceToken)
    }

    func application(_ application: UIApplication,
                     didFailToRegisterForRemoteNotificationsWithError error: Error) {
        NotificationCenter.default.post(name: .capacitorDidFailToRegisterForRemoteNotifications,
                                        object: error)
    }
SWIFT

tail -n +"$LAST_BRACE" "$APPDELEGATE" >> "$TMP"
mv "$TMP" "$APPDELEGATE"

echo "Patched $APPDELEGATE to forward the APNs token to Capacitor."
grep -n "didRegisterForRemoteNotificationsWithDeviceToken\|didFailToRegisterForRemoteNotificationsWithError" "$APPDELEGATE"
